INSERT INTO `chatbot_faqs` (`faq_id`, `question`, `answer`, `keywords`, `enabled`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, CONCAT('How do employee promotions work in the HRMS',CHAR(63),''), 'Employees file a promotion request from their ESS portal (Promotion tab). HR reviews it under Core HCM → Promotion Requests; approving applies the position transfer and history entry immediately.', 'promotion,promotions,regularization,regularize,hr3,evaluation,handoff,salary increase,demote', 1, 90, '2026-10-18 01:06:12', '2026-10-18 01:06:12'),
(2, CONCAT('How do job requisitions become job posts',CHAR(63),''), 'Requisitions are raised in Core HCM (Departments & Positions → Requisitions). Recruitment then converts an approved requisition into a live job post via the Requisitions tab.', 'requisition,requisitions,headcount,vacancy request,job order,hiring request,convert', 1, 91, '2026-10-18 01:06:12', '2026-10-18 01:06:12'),
(3, CONCAT('How do I export a report',CHAR(63),''), 'Every module header has a Generate Report control — use it to export the current view as PDF, DOCX or Excel.', 'report,reports,export,pdf,docx,excel,generate report,download', 1, 92, '2026-10-18 01:06:12', '2026-10-18 01:06:12'),
(4, CONCAT('How do I file a leave request',CHAR(63),''), 'Open the ESS portal, go to Request Center (or Attendance tab for leave balances), pick the leave type and date range, then submit. HR sees it instantly in the ESS Management queue.', 'leave,leave request,vl,sl,file leave,time off,absence,leave credits,attendance', 1, 93, '2026-10-18 01:06:12', '2026-10-18 01:06:12');

